// moveMade: 이미 ✓ 한 앞 번호에서 만든 부품을 나중 번호가 옮길 때(투석기 17번), 앞 번호 데이터는 그대로 두고 나중 번호 단계 데이터에 { "만든번호:부품순서": { p, r, dir, hover, marks, moveGroup } } 로 적는다.
// 읽을 때 그 부품의 move 로 합쳐서, 화면·검사·MCP 도구가 모두 같은 move(at = 옮기는 번호)를 본다. 부품마다 한 번만 옮길 수 있다.
(function () {
  (window.IVS_ASSEMBLIES || []).forEach(function (a) {
    (a.steps || []).forEach(function (s, k) {
      var mm = s.moveMade; if (!mm) return;
      Object.keys(mm).forEach(function (key) {
        var q = key.split(':'), st = a.steps[Number(q[0]) - 1], pt = st && (st.parts || [])[Number(q[1])]; if (!pt) return;
        var e = Object.assign({}, mm[key], { at: k + 1 });
        if (e.moveGroup !== undefined) { pt.moveGroup = e.moveGroup; delete e.moveGroup; }
        pt.moves = pt.moves || (pt.move ? [pt.move] : []); pt.moves.push(e); pt.moves.sort(function (x, y) { return x.at - y.at; }); pt.move = pt.moves[pt.moves.length - 1];   // 여러 번 옮긴 부품(예: 17번 L 묶음 → 21번 몸에 합침): moves 에 모두 쌓고, 단계별 자세는 IVS_moveAt 로 읽는다
      });
    });
  });
})();

// IVS_moveAt(부품, 단계): 그 단계(포함) 이전에 가장 마지막으로 옮겨진 move 를 돌려준다(없으면 null). 한 번만 옮긴 부품은 pt.move 그대로. IVS_moveIs(부품, 단계): 그 단계에 옮겨지는가.
window.IVS_moveAt = function (pt, step) { var ms = pt.moves; if (!ms) return (pt.move && pt.move.at <= step) ? pt.move : null; var best = null; for (var i = 0; i < ms.length; i++) if (ms[i].at <= step && (!best || ms[i].at >= best.at)) best = ms[i]; return best; };
window.IVS_moveIs = function (pt, step) { var ms = pt.moves || (pt.move ? [pt.move] : []); return ms.some(function (m) { return m && m.at === step; }); };
